-- react-native-gadget-shop/supabase/migrations/20260104000000_add_coupons.sql
--
-- Adds coupons: a code, a percentage or flat discount, an optional
-- expiry date, an optional minimum order amount, and an active flag.
-- Redemption tracking (which user used which coupon) is left out of
-- this first pass to keep the chunk small — can be added later if you
-- want to enforce "one use per customer".

create table if not exists "public"."coupon" (
    "id" bigint generated by default as identity primary key,
    "created_at" timestamp with time zone not null default now(),
    "code" text not null unique,
    "discount_type" text not null check (discount_type in ('percentage', 'flat')),
    "discount_value" numeric not null check (discount_value > 0),
    "min_order_amount" numeric not null default 0,
    "expires_at" timestamp with time zone,
    "is_active" boolean not null default true
);

alter table "public"."coupon" enable row level security;

-- Anyone signed in can read active coupons (needed so the app can
-- validate a code the user types in at checkout).
create policy "Active coupons are readable by authenticated users"
on "public"."coupon" for select to authenticated
using (true);

-- Only admin and above can create/update/delete coupons.
create policy "Coupon insert - admin and above"
on "public"."coupon" for insert to authenticated
with check (public.current_user_role() in ('super_admin', 'admin'));

create policy "Coupon update - admin and above"
on "public"."coupon" for update to authenticated
using (public.current_user_role() in ('super_admin', 'admin'))
with check (public.current_user_role() in ('super_admin', 'admin'));

create policy "Coupon delete - admin and above"
on "public"."coupon" for delete to authenticated
using (public.current_user_role() in ('super_admin', 'admin'));
